const state={route:'overview',period:'all',frequency:'hourly',aggregation:'avg',daily:[],hourly:[],reported:[],games:[],history:[],live:[],liveHistory:[],collectionStatus:null,meta:null,selectedGame:null,compare:[]};
const $=s=>document.querySelector(s);const $$=s=>[...document.querySelectorAll(s)];const num=v=>Number.isFinite(Number(v))?Number(v):null;const nf=new Intl.NumberFormat('ko-KR',{maximumFractionDigits:0});const compact=new Intl.NumberFormat('ko-KR',{notation:'compact',maximumFractionDigits:2});const fmt=v=>v==null?'—':nf.format(Math.round(v));const fmtCompact=v=>v==null?'—':compact.format(v);const dateOf=v=>new Date(String(v).includes('T')?v:`${v}T00:00:00Z`);const day=v=>dateOf(v).toISOString().slice(0,10);const esc=v=>String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));const mean=a=>{const v=a.filter(x=>x!=null);return v.length?v.reduce((x,y)=>x+y,0)/v.length:null};
const rangeFor=()=>{const end=new Date(`${$('#endDate').value||day(new Date())}T23:59:59Z`);let start=new Date(`${$('#startDate').value||'2000-01-01'}T00:00:00Z`);const days={"7d":7,"30d":30,"90d":90,"1y":365}[state.period];if(days){start=new Date(end);start.setUTCDate(start.getUTCDate()-days+1)}return{start,end}};
const genreName=v=>({'Action':'액션','Adventure':'어드벤처','Education':'교육','Entertainment':'엔터테인먼트','Obby & Platformer':'장애물·플랫포머','Party & Casual':'파티·캐주얼','Puzzle':'퍼즐','Roleplay & Avatar Sim':'역할극·아바타','RPG':'RPG','Shooter':'슈팅','Shopping':'쇼핑','Simulation':'시뮬레이션','Social':'소셜','Sports & Racing':'스포츠·레이싱','Strategy':'전략','Survival':'생존','Utility & Other':'기타 유틸리티','Uncategorized':'미분류'}[String(v||'').trim()]||String(v||'미분류'));
function allDates(){return state.hourly.map(x=>x.timestamp).concat(state.daily.map(x=>x.date)).filter(Boolean).sort()}function initDates(){const d=allDates();if(!d.length)return;$('#startDate').value=day(d[0]);$('#endDate').value=day(d[d.length-1])}
async function getJson(path,fallback=[]){try{const r=await fetch(path);if(!r.ok)throw Error(r.status);return await r.json()}catch(e){return fallback}}
async function load(){const [daily,hourly,reported,games,history,meta,live,liveHistory,collectionStatus]=await Promise.all([getJson('public/data/platform_daily.json'),getJson('public/data/platform_hourly.json'),getJson('public/data/reported_points.json'),getJson('public/data/games_daily.json'),getJson('public/data/game_history_daily.json'),getJson('public/data/meta.json',{}),getJson('public/data/live_games.json',{}),getJson('public/data/live_game_history.json',{}),getJson('public/data/collection_status.json',{})]);state.daily=daily;state.hourly=hourly;state.reported=reported;state.games=games;const historicRows=Array.isArray(history)?history:(history.data||[]);state.liveHistory=Array.isArray(liveHistory)?liveHistory:(liveHistory.data||[]);state.history=historicRows.concat(state.liveHistory);state.meta=meta;state.live=Array.isArray(live)?live:(live.data||[]);state.collectionStatus=collectionStatus;initDates();$('#trackedGames').textContent=new Set(state.history.map(x=>String(x.universeId))).size.toLocaleString('ko-KR');const latestCollection=collectionStatus.ranAt||live.collectedAt;$('#footerGenerated').textContent=latestCollection?`자동 수집 ${latestCollection.slice(0,16).replace('T',' ')}`:meta.generatedAt?`데이터 생성 ${meta.generatedAt.slice(0,10)}`:'정적 데이터 묶음';renderAll()}
function latestRows(){const m=new Map();for(const r of state.history){const id=String(r.universeId);const old=m.get(id);if(!old||String(r.date)>String(old.date)||(String(r.date)===String(old.date)&&r.source==='bloxscout_daily'))m.set(id,r)}return[...m.values()]}
function gameRows(){const rg=rangeFor();const q=($('#gameSearch')?.value||'').trim().toLowerCase();const m=new Map();for(const r of state.history){const d=dateOf(r.date);if(d<rg.start||d>rg.end)continue;const text=`${r.name} ${r.universeId}`.toLowerCase();if(q&&!text.includes(q))continue;const id=String(r.universeId);if(!m.has(id))m.set(id,{id,name:r.name||`게임 ${id}`,genre:genreName(r.genre),avg:[],peak:[],days:new Set(),start:r.date,end:r.date});const g=m.get(id);if(r.avg!=null)g.avg.push(num(r.avg));if(r.peak!=null)g.peak.push(num(r.peak));g.days.add(day(r.date));if(r.date<g.start)g.start=r.date;if(r.date>g.end)g.end=r.date}return[...m.values()].map(g=>({...g,avg:mean(g.avg),peak:g.peak.length?Math.max(...g.peak):null,days:g.days.size})).sort((a,b)=>(b.avg||0)-(a.avg||0))}
function gameGrowth(id){const pts=state.history.filter(r=>String(r.universeId)===String(id)&&r.avg!=null).sort((a,b)=>String(a.date).localeCompare(String(b.date)));if(pts.length<2)return null;const prev=num(pts.at(-2).avg),last=num(pts.at(-1).avg);return prev?((last-prev)/prev)*100:null}
function platformPoints(){const rg=rangeFor();if(state.frequency==='hourly')return state.hourly.filter(r=>{const d=dateOf(r.timestamp);return d>=rg.start&&d<=rg.end}).map(r=>({date:r.timestamp,value:num(r[state.aggregation==='avg'?'ccu':'peak'])}));const src=state.daily.filter(r=>{const d=dateOf(r.date);return d>=rg.start&&d<=rg.end});if(state.frequency==='daily')return src.map(r=>({date:r.date,value:num(r[state.aggregation])}));const b=new Map();for(const r of src){const d=dateOf(r.date);const k=state.frequency==='weekly'?weekKey(d):`${d.getUTCFullYear()}-${String(d.getUTCMonth()+1).padStart(2,'0')}`;if(!b.has(k))b.set(k,[]);b.get(k).push(num(r[state.aggregation]))}return[...b].sort((a,b)=>a[0].localeCompare(b[0])).map(([date,v])=>({date,value:state.aggregation==='avg'?mean(v):Math.max(...v)}))}
function weekKey(d){const x=new Date(Date.UTC(d.getUTCFullYear(),d.getUTCMonth(),d.getUTCDate()));const n=x.getUTCDay()||7;x.setUTCDate(x.getUTCDate()-n+1);return day(x)}function labelFor(v){const d=dateOf(v),y=d.getUTCFullYear(),m=String(d.getUTCMonth()+1).padStart(2,'0'),dd=String(d.getUTCDate()).padStart(2,'0');if(state.frequency==='monthly')return`${y}.${m}`;if(state.frequency==='hourly')return`${y}.${m}.${dd} ${String(d.getUTCHours()).padStart(2,'0')}시`;return`${y}.${m}.${dd}`}
function drawChart(canvas,series,{emptyEl=null,colors=['#4c91ff'],yMax=null}={}){const rect=canvas.getBoundingClientRect();if(!rect.width||!rect.height)return;const dpr=window.devicePixelRatio||1;canvas.width=rect.width*dpr;canvas.height=rect.height*dpr;const c=canvas.getContext('2d');c.setTransform(dpr,0,0,dpr,0,0);const w=rect.width,h=rect.height,p={l:62,r:22,t:18,b:43};c.clearRect(0,0,w,h);const usable=series.filter(s=>s.points?.length);if(!usable.length){emptyEl?.classList.remove('hidden');return}emptyEl?.classList.add('hidden');const all=usable.flatMap(s=>s.points.map(x=>x.value)).filter(x=>x!=null);const max=yMax||Math.max(...all)*1.1||1;const x=(i,n)=>p.l+(w-p.l-p.r)*(n===1?.5:i/(n-1));const y=v=>h-p.b-(h-p.t-p.b)*(v/max);c.font='10px Inter, sans-serif';c.lineWidth=1;c.strokeStyle='#223047';c.fillStyle='#718097';for(let i=0;i<=5;i++){const yy=p.t+(h-p.t-p.b)*i/5;c.beginPath();c.moveTo(p.l,yy);c.lineTo(w-p.r,yy);c.stroke();c.fillText(fmtCompact(max-(max*i/5)),8,yy+4)}for(let si=0;si<usable.length;si++){const pts=usable[si].points;c.strokeStyle=colors[si%colors.length];c.lineWidth=2.25;c.beginPath();pts.forEach((pt,i)=>{const px=x(i,pts.length),py=y(pt.value);if(i===0)c.moveTo(px,py);else{const gap=dateOf(pt.date)-dateOf(pts[i-1].date);const limit=state.frequency==='hourly'?3*3600000:state.frequency==='daily'?3*86400000:state.frequency==='weekly'?15*86400000:45*86400000;if(gap>limit)c.moveTo(px,py);else c.lineTo(px,py)}});c.stroke()}const base=usable[0].points;const every=Math.max(1,Math.floor(base.length/7));c.fillStyle='#748197';base.forEach((pt,i)=>{if(i%every&&i!==base.length-1)return;const text=labelFor(pt.date),tw=c.measureText(text).width,px=x(i,base.length);c.fillText(text,Math.max(p.l,Math.min(w-p.r-tw,px-tw/2)),h-15)})}
function renderPlatform(){const points=platformPoints().filter(x=>x.value!=null);const avg=mean(points.map(x=>x.value)),peak=points.length?Math.max(...points.map(x=>x.value)):null;$('#summaryAvg').textContent=fmt(avg);$('#summaryPeak').textContent=fmt(peak);$('#summaryPoints').textContent=points.length.toLocaleString('ko-KR');$('#summaryPointsSub').textContent=state.frequency==='hourly'?'원시 시간별 관측':'선택 주기로 집계';const last=points.at(-1);$('#summaryFreshness').textContent=last?day(last.date):'—';$('#summaryFreshnessSub').textContent=last?`마지막 관측 시각 ${String(last.date).includes('T')?dateOf(last.date).toISOString().slice(11,16)+' 세계협정시':''}`:'데이터 없음';$('#chartSubtitle').textContent=`${{hourly:'시간별',daily:'일별',weekly:'주별',monthly:'월별'}[state.frequency]} · ${state.aggregation==='avg'?'평균':'피크'} · ${state.period==='all'?'전체 기간':state.period}`;$('#chartStatus').textContent=`${points.length.toLocaleString('ko-KR')}개 포인트 · 추정값 없음`;$('#dataStatus').textContent=`플랫폼 ${state.meta?.coverage?.platformDaily?.start||'—'} ~ ${state.meta?.coverage?.platformDaily?.end||'—'}`;const lastHour=state.hourly.at(-1),lastDay=state.daily.at(-1);$('#latestCcu').textContent=fmt(num(lastHour?.ccu??lastDay?.avg));drawChart($('#usageChart'),[{points}],{emptyEl:$('#emptyState'),colors:['#4c91ff']})}
function renderTop(){const rows=latestRows().filter(x=>x.avg!=null).sort((a,b)=>(b.avg||0)-(a.avg||0)).slice(0,8);$('#topGames').innerHTML=rows.map((r,i)=>`<div class="rank-row"><span class="rank-no">${String(i+1).padStart(2,'0')}</span><span class="rank-name">${esc(r.name)}<small class="rank-sub">${esc(genreName(r.genre))}</small></span><span class="rank-value">${fmt(r.avg)}<small class="rank-sub">CCU</small></span></div>`).join('')||'<div class="muted">게임 데이터가 없습니다.</div>';const counts=new Map();for(const r of rows){const g=genreName(r.genre);counts.set(g,(counts.get(g)||0)+(r.avg||0))}const bars=[...counts].sort((a,b)=>b[1]-a[1]).slice(0,6),total=bars.reduce((a,b)=>a+b[1],0);$('#genreBars').innerHTML=bars.map(([g,v])=>`<div class="bar-item"><label>${esc(g)}</label><div class="bar-track"><i style="width:${total?Math.max(4,v/total*100):0}%"></i></div><b>${total?Math.round(v/total*100):0}%</b></div>`).join('')||'<div class="muted">장르 데이터가 없습니다.</div>'}
function renderGames(){const rows=gameRows().slice(0,100);$('#gameTable').innerHTML=rows.map(g=>{const growth=gameGrowth(g.id);const growthText=growth==null?'—':`${growth>=0?'+':''}${growth.toFixed(1)}%`;return`<tr data-game-id="${esc(g.id)}"><td class="game-name">${esc(g.name)}<small class="rank-sub">${esc(g.id)}</small></td><td class="muted">${esc(g.genre)}</td><td>${fmt(g.avg)}</td><td>${fmt(g.peak)}</td><td class="${growth!=null&&growth>=0?'growth-up':growth!=null?'growth-down':'muted'}">${growthText}</td><td>${g.days.toLocaleString('ko-KR')}일</td><td class="muted">${g.start} ~ ${g.end}</td></tr>`}).join('')||'<tr><td colspan="7" class="muted">선택한 범위에 게임 데이터가 없습니다.</td></tr>';$('#gameTableFooter').textContent=rows.length?`${rows.length.toLocaleString('ko-KR')}개 표시 · 실제 관측일만 집계`:'게임 데이터가 없습니다.';$$('#gameTable tr[data-game-id]').forEach(tr=>tr.addEventListener('click',()=>showGame(tr.dataset.gameId)))}
function showGame(id){state.selectedGame=id;const rows=state.history.filter(r=>String(r.universeId)===String(id)).sort((a,b)=>String(a.date).localeCompare(String(b.date)));if(!rows.length)return;const name=rows.at(-1).name||`게임 ${id}`,pts=rows.filter(r=>r.avg!=null).map(r=>({date:r.date,value:num(r.avg)}));const sourceNames=new Set(rows.map(r=>r.source==='early_shift_daily'?'초기 일별 아카이브':r.source==='bloxscout_daily'?'게임 공개 일별 관측':r.source==='roblox_public_games_api'?'Roblox 공개 게임 API':'공개 일별 관측'));const growth=gameGrowth(id);$('#detailName').textContent=name;$('#detailMeta').textContent=`유니버스 ID ${id} · ${genreName(rows.at(-1).genre)} · ${pts.length.toLocaleString('ko-KR')}개 관측 포인트`;$('#detailLatest').textContent=fmt(pts.at(-1)?.value);$('#detailGrowth').textContent=growth==null?'—':`${growth>=0?'+':''}${growth.toFixed(1)}%`;$('#detailPeak').textContent=fmt(Math.max(...pts.map(x=>x.value)));$('#detailDays').textContent=pts.length.toLocaleString('ko-KR');$('#detailSourceNote').textContent=`원천: ${[...sourceNames].join(', ')}`;$('#gameDetail').classList.remove('hidden');drawChart($('#gameChart'),[{points:pts}],{emptyEl:$('#gameEmpty'),colors:['#4c91ff']});$('#gameDetail').scrollIntoView({behavior:'smooth',block:'start'})}
function renderCompareOptions(){const select=$('#compareGameSelect'),old=select.value;select.innerHTML='<option value="">게임을 선택하세요</option>'+latestRows().filter(x=>x.name).sort((a,b)=>(b.avg||0)-(a.avg||0)).slice(0,300).map(r=>`<option value="${esc(r.universeId)}">${esc(r.name)} · ${fmt(r.avg)} CCU</option>`).join('');if(old)select.value=old;const colors=['#4c91ff','#b58aff','#25c98b','#e9ad45','#f05e7e'];$('#compareChips').innerHTML=state.compare.map((id,i)=>{const r=latestRows().find(x=>String(x.universeId)===String(id));return`<span class="compare-chip" style="border-color:${colors[i]}"><i class="dot" style="background:${colors[i]}"></i>${esc(r?.name||id)}<button data-remove-compare="${id}" type="button">×</button></span>`}).join('')||'<span class="muted">아직 선택한 게임이 없습니다.</span>';$$('[data-remove-compare]').forEach(b=>b.addEventListener('click',()=>{state.compare=state.compare.filter(x=>x!==b.dataset.removeCompare);renderCompareOptions();renderCompare()}));$('#compareHelper').textContent=state.compare.length?`${state.compare.length}개 게임을 비교 중입니다.`:'게임을 추가하면 차트가 표시됩니다.'}
function renderCompare(){const colors=['#4c91ff','#b58aff','#25c98b','#e9ad45','#f05e7e'];const series=state.compare.map(id=>({points:state.history.filter(r=>String(r.universeId)===String(id)&&r.avg!=null).sort((a,b)=>String(a.date).localeCompare(String(b.date))).map(r=>({date:r.date,value:num(r.avg)}))}));drawChart($('#compareChart'),series,{emptyEl:$('#compareEmpty'),colors})}
function renderGenres(){const rows=latestRows().filter(r=>r.avg!=null);const m=new Map();for(const r of rows){const g=genreName(r.genre);if(!m.has(g))m.set(g,{value:0,games:0});m.get(g).value+=r.avg;m.get(g).games++}const list=[...m].sort((a,b)=>b[1].value-a[1].value),total=list.reduce((a,x)=>a+x[1].value,0);$('#genreTable').innerHTML=list.map(([g,v])=>`<div class="genre-row"><span>${esc(g)}</span><div class="genre-bar"><i style="width:${total?Math.max(2,v.value/total*100):0}%"></i></div><strong>${fmt(v.value)}</strong><small>${v.games.toLocaleString('ko-KR')}개 · ${total?Math.round(v.value/total*100):0}%</small></div>`).join('')||'<div class="muted">장르 데이터가 없습니다.</div>'}
function renderCoverage(){const c=state.meta?.coverage||{};const liveDates=state.liveHistory.map(r=>day(r.date)).filter(Boolean).sort();const liveRange=liveDates.length?{start:liveDates[0],end:liveDates.at(-1)}:null;const cards=[['플랫폼 일별',c.platformDaily],['플랫폼 시간별',c.platformHourly],['게임 일별',c.gameDaily],['게임 장기 시계열',c.gameHistoryDaily],['실시간 게임 API',liveRange]];$('#coverageCards').innerHTML=cards.map(([name,v])=>`<div class="coverage-card"><b>${name}</b><span>확보된 날짜 범위</span><strong>${v?.start||'—'}<br />~ ${v?.end||'—'}</strong></div>`).join('')}
function renderCreators(){const has=state.live.length&&state.live.some(x=>x.creator);$('#creatorPanel').innerHTML=has?'<h3>공개 API 스냅샷 기반 제작자 집계</h3><p>공개 게임 API 스냅샷에서 제작자 필드가 확인된 게임만 제작자별로 묶습니다.</p>':'<h3>제작자 데이터 대기 중</h3><p>현재 장기 게임 CSV에는 제작자 필드가 보존되어 있지 않습니다. 공개 Roblox 게임 API 스냅샷 수집기를 실행해 제작자 정보를 쌓으면 이 화면에서 제작자별 게임 수와 CCU를 계산할 수 있습니다.</p><div class="coverage-notes"><span>공개 API 스냅샷 파일</span><span>현재 게임 데이터에는 제작자 미포함</span></div>'}
function routeTo(route){state.route=route;$$('.view').forEach(v=>v.classList.toggle('hidden',v.dataset.view!==route));$$('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.route===route));const titles={overview:['로블록스 사용량 개요','플랫폼과 게임의 공개 관측값을 한 화면에서 확인합니다.'],games:['게임별 사용량','수집된 원시 일별 CCU를 게임 단위로 확인합니다.'],compare:['게임별 CCU 비교','최대 5개 게임의 장기 시계열을 같은 축에서 비교합니다.'],discovery:['발견 보드 분석','로블록스 홈 노출 보드의 진입·이탈·체류를 기록합니다.'],creators:['제작자 분석','공개 게임 API 스냅샷에서 제작자별 사용량을 묶습니다.'],genres:['장르별 사용량','최근 게임별 관측 CCU를 장르별로 합산합니다.'],coverage:['데이터 범위','원천별 실제 확보 범위와 공백을 확인합니다.']};$('#pageTitle').textContent=titles[route][0];$('#pageSubtitle').textContent=titles[route][1];if(route==='compare'){renderCompareOptions();renderCompare()}if(route==='games')renderGames();if(route==='genres')renderGenres();if(route==='coverage')renderCoverage();if(route==='creators')renderCreators();if(route==='overview'){renderPlatform();renderTop()}}
function renderAll(){routeTo(state.route)}
function download(name,content,type){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([content],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500)}function currentExport(format){const data=platformPoints().filter(x=>x.value!=null);if(format==='json')download('로블록스-플랫폼-관측값.json',JSON.stringify({정책:'추정 DAU와 보간 없음',주기:state.frequency,집계:state.aggregation,data},null,2),'application/json');else download('로블록스-플랫폼-관측값.csv',['timestamp,value',...data.map(x=>`${x.date},${x.value}`)].join('\n'),'text/csv')}
$$('.nav-item').forEach(b=>b.addEventListener('click',()=>routeTo(b.dataset.route)));$$('[data-route]').forEach(b=>{if(!b.classList.contains('nav-item'))b.addEventListener('click',()=>routeTo(b.dataset.route))});for(const group of ['period','frequency','aggregation'])$(`#${group}Controls`)?.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;state[group]=b.dataset[group];$$(`#${group}Controls button`).forEach(x=>x.classList.toggle('active',x===b));if(group==='period'&&state.period!=='all'){const r=rangeFor();$('#startDate').value=day(r.start);$('#endDate').value=day(r.end)}renderPlatform();renderTop();if(state.route==='games')renderGames()});
$('#applyDates')?.addEventListener('click',()=>{state.period='custom';$$('#periodControls button').forEach(b=>b.classList.remove('active'));renderPlatform();renderTop();renderGames()});$('#gameSearch')?.addEventListener('input',renderGames);$('#downloadCsv')?.addEventListener('click',()=>currentExport('csv'));$('#downloadJson')?.addEventListener('click',()=>currentExport('json'));$('#fullscreen')?.addEventListener('click',()=>document.querySelector('.chart-panel')?.requestFullscreen?.());$('#closeGameDetail')?.addEventListener('click',()=>$('#gameDetail').classList.add('hidden'));$('#addCompare')?.addEventListener('click',()=>{const id=$('#compareGameSelect').value;if(!id||state.compare.includes(id)||state.compare.length>=5)return;state.compare.push(id);$('#compareGameSelect').value='';renderCompareOptions();renderCompare()});$('#clearCompare')?.addEventListener('click',()=>{state.compare=[];renderCompareOptions();renderCompare()});window.addEventListener('resize',()=>{if(state.route==='overview')renderPlatform();if(state.route==='compare')renderCompare();if(state.selectedGame&&!$('#gameDetail').classList.contains('hidden'))showGame(state.selectedGame)});load().catch(e=>{console.error(e);$('#dataStatus').textContent='데이터를 불러오지 못했습니다.'});
